            description = "Templates for your next project.",
            visibility = CatalogVisibility.Hidden,
        )
    val product = client.products.getSuspend(created.data.id.toString())
    return client.products
        .updateSuspend(product.data.id.toString(), title = PatchField.Present("Design kit revised"))
