fun describeError(error: Exception): String =
    when (error) {
        is SellAppApiException ->
            "API status ${error.status}: ${error.message} (request ${error.requestId ?: "unavailable"})"
        is SellAppTimeoutException -> "Request timed out: ${error.message}"
        else -> "Request failed: ${error.message}"
    }

